'use strict';

// The converted ship models under src/renderer/ships/<ship>/source/ are generated files
// (scripts/import-ship.mjs). These tests hold them to the record the script wrote beside them, so
// a hand edit, a missing script tag or a model that no longer builds fails here.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const BABYLON = require('babylonjs');
const { lf, sha256, fingerprintOf, loadShipModules, rootOf } = require('../scripts/lib/ship-fingerprint.js');
const { scriptTags } = require('./support/renderer-source');

const SHIPS = path.join(__dirname, '..', 'src', 'renderer', 'ships');
const scripts = scriptTags();
const ships = fs.readdirSync(SHIPS, { withFileTypes: true })
  .filter((entry) => entry.isDirectory() && fs.existsSync(path.join(SHIPS, entry.name, 'source', 'source.json')))
  .map((entry) => entry.name);
const recordOf = (ship) => JSON.parse(fs.readFileSync(path.join(SHIPS, ship, 'source', 'source.json'), 'utf8'));
const modulesOf = (ship) => Object.keys(recordOf(ship).modules).map((stem) => path.join(SHIPS, ship, 'source', stem + '.js'));

test('at least one ship model is converted, Petrel with its survey ring as a variant', () => {
  assert.ok(ships.includes('petrel'));
  assert.deepEqual(recordOf('petrel').variants.ring.call, ['setRing', true]);
});

test('Breakwater is built on Petrel: it borrows that ship\'s modules and converts none of them again', () => {
  const { borrows, modules } = recordOf('breakwater');
  assert.equal(borrows, 'petrel');
  assert.deepEqual(Object.keys(modules).filter((stem) => stem in recordOf('petrel').modules), []);
  const yard = fs.readFileSync(path.join(SHIPS, 'breakwater', 'source', 'yard.js'), 'utf8');
  assert.ok(yard.includes("use('petrel/spacecraft')"), 'the ships parked on it are the Petrel the fleet flies');
});

test('every folder under ships/ is a converted model with its adapter', () => {
  const folders = fs.readdirSync(SHIPS, { withFileTypes: true }).filter((entry) => entry.isDirectory()).map((entry) => entry.name);
  assert.deepEqual(folders, ships);
  for (const ship of ships) assert.ok(fs.existsSync(path.join(SHIPS, ship, 'model.js')), ship + '/model.js');
});

for (const ship of ships) {
  const dir = path.join(SHIPS, ship, 'source');
  const record = recordOf(ship);
  const stems = Object.keys(record.modules);

  test(`${ship}: the folder holds exactly the recorded modules, as the script generated them`, () => {
    assert.equal(record.ship, ship);
    assert.match(record.commit, /^[0-9a-f]{12}$/, 'converted from a clean source commit');
    assert.deepEqual(fs.readdirSync(dir).sort(), [...stems.map((stem) => stem + '.js'), 'source.json'].sort());
    for (const stem of stems) {
      const text = lf(fs.readFileSync(path.join(dir, stem + '.js'), 'utf8'));
      const lines = text.split('\n');
      assert.equal(lines[0], '// @ts-check', stem);
      assert.match(lines[1], /^\/\/ Generated by scripts\/import-ship\.mjs /, stem);
      assert.ok(lines.length <= 400, `${stem}.js is ${lines.length} lines`);
      assert.equal(sha256(text), record.modules[stem].generated,
        `${stem}.js is not what scripts/import-ship.mjs wrote: change the ship at its source and run the script`);
    }
  });

  // The page builds nothing at load, so the order among a ship's modules is free; the registry
  // comes before them, the model registry before the adapter, and all of it before ship-assets.
  test(`${ship}: index.html loads the registry, the modules, the model registry and the adapter, in that order`, () => {
    const at = (file) => {
      assert.ok(scripts.includes(file), file + ' has a script tag');
      return scripts.indexOf(file);
    };
    const modules = stems.map((stem) => at(`ships/${ship}/source/${stem}.js`));
    assert.ok(Math.min(...modules) > at('ships/modules.js'), 'the modules load after ships/modules.js');
    assert.ok(at('ships/models.js') > at('ships/modules.js'));
    assert.ok(at(`ships/${ship}/model.js`) > at('ships/models.js'), 'the adapter registers with ships/models.js');
    assert.ok(at('ship-assets.js') > at(`ships/${ship}/model.js`), 'ship-assets finds the model registered');
    if (record.borrows) {
      assert.ok(at(`ships/${ship}/model.js`) > at(`ships/${record.borrows}/model.js`), 'its adapter reads the adapter of the ship it is built on');
    }
  });

  test(`${ship}: the modules export what was recorded and build the recorded ship`, () => {
    const use = loadShipModules(BABYLON, path.join(SHIPS, 'modules.js'),
      [...(record.borrows ? modulesOf(record.borrows) : []), ...modulesOf(ship)]);
    for (const stem of stems) {
      assert.deepEqual(Object.keys(use(`${ship}/${stem}`)), record.modules[stem].exports, stem);
    }
    const [module, build] = record.build;
    // The fingerprint of the ship the recorded build makes, after a variant's call when one is given.
    const built = (call) => fingerprintOf(BABYLON, (scene) => rootOf(use(`${ship}/${module}`)[build](scene), call));
    assert.deepEqual(built(), record.geometry);
    for (const [name, { call, geometry }] of Object.entries(record.variants)) assert.deepEqual(built(call), geometry, name);
  });
}
